                    detail: format!("canonical manifest `{path}` has no canonical manifest format"),
                })?;
            callisto_manifests::read_effective_version(format, source, std::path::Path::new(path), cargo_workspace)
                .map_err(historical_manifest_error)?
                .ok_or_else(|| {
