}

fn reason_from_bump(
    reason: Option<&BumpReason>,
    package_ids: &std::collections::BTreeMap<callisto_model::PackageId, Vec<ReleasePackageId>>,
) -> Result<ReleaseInclusionReason, GraphError> {
    match reason {
        Some(BumpReason::Changeset { .. }) | None => Ok(ReleaseInclusionReason::Changeset),
        Some(BumpReason::Inference { .. }) => Ok(ReleaseInclusionReason::Inference),
        Some(BumpReason::LinkedGroupUnion { group }) => Ok(ReleaseInclusionReason::LinkedGroup {
            group_id: group.to_string(),
        }),
        Some(BumpReason::FixedGroupUnion { group } | BumpReason::NewGroupMember { group }) => {
            Ok(ReleaseInclusionReason::FixedGroup {
                group_id: group.to_string(),
            })
        }
        Some(BumpReason::PreRelease { tag }) => Ok(ReleaseInclusionReason::PreReleasePolicy { policy_id: tag.clone() }),
        Some(BumpReason::Cascade { via, dep_kind, .. }) => {
            // `package_ids` is derived from the same workspace graph `via`
            // was resolved against, so a miss (or a non-unique release
            // identity) here means that pairing broke, not that this is a
            // recoverable operator condition.
            let source = package_ids
                .get(via)
                .and_then(|ids| (ids.len() == 1).then(|| ids[0].clone()))
                .ok_or_else(|| GraphError::ReleaseInvariant {
                    detail: format!(
                        "cascade source package `{}` has no unique release package id",
                        via.display_name()
                    ),
                })?;
            Ok(ReleaseInclusionReason::Cascade {
                from: source,
                edge_kind: format!("{dep_kind:?}"),
            })
        }
        Some(BumpReason::PeerEscalation { via, .. }) => {
            let source = package_ids
                .get(via)
                .and_then(|ids| (ids.len() == 1).then(|| ids[0].clone()))
                .ok_or_else(|| GraphError::ReleaseInvariant {
                    detail: format!(
                        "peer-escalation source package `{}` has no unique release package id",
                        via.display_name()
                    ),
                })?;
            Ok(ReleaseInclusionReason::Cascade {
                from: source,
                edge_kind: "peer".to_string(),
            })
        }
        Some(_) => Err(GraphError::UnsupportedRelease {
            feature: UnsupportedReleaseFeature::BumpReason,
        }),
    }
}

#[cfg(test)]
mod tests {
    use callisto_model::{Ecosystem, Version};

    use super::*;

    #[test]
    fn decision_is_canonical_and_ecosystem_qualified() {
        let cargo = ReleasePackageId::new(Ecosystem::Cargo, "demo").unwrap();
        let npm = ReleasePackageId::new(Ecosystem::Npm, "demo").unwrap();
        let first = ReleaseDecisionV1::new(vec![
            ReleaseDecisionEntry {
                package: npm,
                target_version: Version::semver(1, 0, 0),
                reasons: vec![ReleaseInclusionReason::ExplicitSelection],
            },
            ReleaseDecisionEntry {
                package: cargo,
                target_version: Version::semver(1, 0, 0),
                reasons: vec![ReleaseInclusionReason::ExplicitSelection],
            },
        ])
        .unwrap();
        assert_eq!(first.entries[0].package.to_string(), "cargo/demo");
        assert_ne!(first.entries[0].package, first.entries[1].package);
    }

    #[test]
    fn release_commit_delta_parser_accepts_only_unambiguous_path_statuses() {
        let args = ["diff-tree", "--name-status"];
        assert_eq!(
            parse_name_status("M\tCargo.toml\nD\t.changeset/release.md\n", &args).unwrap(),
            vec![
                ("M".to_string(), "Cargo.toml".to_string()),
                ("D".to_string(), ".changeset/release.md".to_string()),
            ]
        );
        assert!(parse_name_status("R100\told\tnew\n", &args).is_err());
        assert!(parse_name_status("M Cargo.toml\n", &args).is_err());
    }

    /// Regression: both malformed name-status lines must
    /// surface as `GraphError::ReleaseCommand` (E164) with a
    /// `CommandFailure::MalformedOutput` cause naming the real `git`
    /// program/args, not the old fieldless `ReleaseIntentStale`.
    #[test]
    fn release_commit_delta_parser_reports_malformed_output_not_stale_intent() {
        let args = ["diff-tree", "--name-status"];
        let err = parse_name_status("R100\told\tnew\n", &args).unwrap_err();
        match err {
            GraphError::ReleaseCommand {
                program,
                failure: CommandFailure::MalformedOutput { .. },
                ..
            } => assert_eq!(program, "git"),
            other => panic!("expected ReleaseCommand{{failure: MalformedOutput}}, got {other:?}"),
        }
    }

    struct FixedBlobRunner(&'static str);

    impl CommandRunner for FixedBlobRunner {
        fn run(
            &self,
            _program: &str,
            _args: &[&str],
            _cwd: &std::path::Path,
        ) -> Result<callisto_model::CommandOutput, callisto_model::CommandError> {
            Ok(callisto_model::CommandOutput {
                exit_code: Some(0),
                stdout: self.0.to_string(),
                stderr: String::new(),
            })
        }
    }

    /// Test-only: single-object equivalent of the batched
    /// `git cat-file --batch` path production code now uses (see
    /// `batch_manifest_blobs_at`/`resolve_batch_versions`), kept only so
    /// the two tests below can exercise `parse_manifest_version`'s parsing
        batch_manifest_blobs_at(workspace.runner, &workspace.root, release_commit.as_str(), &query_paths)?;
    let before_versions = resolve_batch_versions(before_blobs, &query_paths, &manifest_queries)?;
    let after_versions = resolve_batch_versions(after_blobs, &query_paths, &manifest_queries)?;

    let mut observed = std::collections::BTreeSet::new();
    let mut manifest_index = 0usize;
    for package in workspace.graph.packages() {
        let package_ids = release_package_ids(&workspace.identity, package)?;
        let package_is_claimed = package_ids.iter().any(|id| claimed.contains_key(id));
        if package_is_claimed {
            let changelog = package.changelog.as_ref().ok_or(GraphError::ReleasePreconditionUnmet {
                requirement: ReleasePreconditionRequirement::ChangelogConfigured,
            })?;
            let changelog = normalized_git_path(changelog)?;
            if !changed_paths.contains(changelog.as_str()) {
                return Err(GraphError::ReleaseCommitVerificationFailed {
                    commit: release_commit.clone(),
                    reason: CommitVerificationFailure::ChangelogNotTouched,
                });
            }
        }
        for id in package_ids {
            let before = &before_versions[manifest_index];
            let after = &after_versions[manifest_index];
            manifest_index += 1;
            let changed_version = before.version != after.version;
            match claimed.get(&id) {
                Some(target_version) => {
                    if !changed_paths.contains(after.authority.to_string_lossy().as_ref()) {
                        return Err(GraphError::ReleaseCommitVerificationFailed {
                            commit: release_commit.clone(),
                            reason: CommitVerificationFailure::ManifestNotInDiff,
                        });
                    }
                    if !changed_version || &after.version != target_version {
                        return Err(GraphError::ReleaseCommitVerificationFailed {
                            commit: release_commit.clone(),
                            reason: CommitVerificationFailure::ManifestVersionMismatch,
                        });
                    }
                    observed.insert(id);
                }
                None => {
                    if changed_version {
                        // A changed version the committed decision never
                        // claimed is not this commit's authority -- fail
                        // closed rather than trust a partial match.
                        return Err(GraphError::ReleaseCommitVerificationFailed {
                            commit: release_commit.clone(),
                            reason: CommitVerificationFailure::UnclaimedVersionChange,
                        });

