 24	/// Package identity extracted directly from manifest source text via
 25	/// [`read_identity`], without going through the full `Manifest::open`
 26	/// lifecycle (workspace-inheritance context, on-disk path resolution,
 27	/// atomic-write machinery). For callers that already hold a manifest's
 28	/// content as a string -- a `git show` blob, a walker's pre-read buffer --
 29	/// and only need the package's name and/or where its version comes from.
 30	#[derive(Clone, Debug, Default, PartialEq, Eq)]
 31	pub struct ManifestIdentity {
 32	    pub name: Option<String>,
 33	    pub version: Option<VersionSource>,
 34	}
 35	
 36	/// Where a manifest's version declaration comes from. Distinct from a raw
 37	/// `Option<String>` so Cargo's `version.workspace = true` is a real,
 38	/// distinguishable case instead of being silently collapsed into "no
 39	/// version present". [`read_identity`] never resolves the inherited value
 40	/// (it has no workspace context); [`read_effective_version`] resolves supplied blobs.
 41	#[derive(Clone, Debug, PartialEq, Eq)]
 42	pub enum VersionSource {
 43	    Literal(String),
 44	    InheritedFromWorkspace,
 45	}
 46	
 47	#[derive(Clone, Debug, PartialEq, Eq)]
 48	pub struct EffectiveManifestVersion {
 49	    pub version: Version,
 50	    pub authority: std::path::PathBuf,
 51	}
 52	
 53	/// Resolves supplied blobs without I/O; paths must already be normalized and workspace-relative.
 54	pub fn read_effective_version(
 55	    format: ManifestFormat,
 56	    source: &str,
 57	    path: &Path,
 58	    cargo_workspace: Option<(&Path, &str)>,
 59	) -> Result<Option<EffectiveManifestVersion>, ManifestError> {
 60	    let identity = read_identity(format, source, path)?;
 61	    let (version, authority) = match identity.version {
 62	        Some(VersionSource::Literal(raw)) => {
 63	            let version = Version::parse(&raw, format.ecosystem().version_grammar()).map_err(|source| {
 64	                ManifestError::InvalidVersion {
