399	/// True when `HEAD`'s tree still has an unconsumed changeset file, read from the commit, not the working tree.
400	fn head_has_pending_changeset<R: CommandRunner, D: DependencyResolver>(
401	    ws: &Workspace<'_, R, D>,
402	    head: &str,
403	) -> Result<bool, GraphError> {
404	    let dir = super::release_decision::normalized_git_path(&ws.config.changesets_dir)?;
405	    let spec = format!("{head}:{dir}");
406	    if !head_object_exists(ws, &spec)? {
407	        // The changesets directory didn't exist at HEAD (e.g. the first `version` run); nothing left pending.
408	        return Ok(false);
409	    }
410	    let output = ws
411	        .runner
412	        .run("git", &["ls-tree", "--name-only", &spec], &ws.root)
413	        .map_err(GraphError::Command)?;
414	    if !output.success() {
415	        return Ok(false);
416	    }
417	    Ok(output.stdout.lines().any(|name| {
418	        let name = name.trim();
419	        name.ends_with(".md") && name != "README.md"
420	    }))
421	}
