619	/// One object's content as reported by `git cat-file --batch`, for a single
620	/// requested `<commit>:<path>`.
621	enum BatchBlob {
622	    /// The path resolved to a blob at the queried commit; this is its raw
623	    /// content.
624	    Blob(String),
625	    /// The path did not exist at the queried commit -- e.g. a package's
626	    /// manifest that was only added later, so it has no blob yet at an
627	    /// earlier `parent` commit.
628	    Missing,
629	}
