316	    let Ok(head) = ws.git_access().head_sha() else {
317	        return Ok(());
318	    };
319	    let head = head.as_str();
320	
321	    // A pre-release cycle legitimately reruns `version` uncommitted; the staged-manifest check is scoped past it.
322	    let in_pre_release_cycle = ws.root.join(ws.config.pre_json_path()).exists();
323	
324	    let pending = head_has_pending_changeset(ws, head)?
325	        || (!in_pre_release_cycle && any_canonical_manifest_staged_uncommitted(ws)?);
326	    if !pending {
327	        return Ok(());
328	    }
329	
330	    let cargo_root = if ws
331	        .graph
332	        .packages()
333	        .flat_map(|pkg| pkg.canonical_manifests())
334	        .any(|decl| decl.ecosystem() == callisto_model::Ecosystem::Cargo)
335	    {
336	        manifest_blob_at(ws, head, "Cargo.toml")?
337	    } else {
338	        None
339	    };
340	    let base_versions = ws.base_versions()?;
341	    for pkg in ws.graph.packages() {
342	        let Some(disk) = base_versions.get(&pkg.id) else {
343	            continue;
344	        };
345	        for decl in pkg.canonical_manifests() {
346	            let path = super::release_decision::normalized_git_path(&decl.path)?;
347	            let Some(head_version) = manifest_version_at(ws, head, &path, cargo_root.as_deref())? else {
348	                continue;
349	            };
350	            if *disk != head_version.version {
351	                return Err(GraphError::PartialVersionRun {
352	                    path: head_version.authority,
353	                    disk: disk.clone(),
354	                    head: head_version.version,
355	                });
356	            }
357	        }
358	    }
359	
360	    Ok(())
361	}
