400	fn head_has_pending_changeset<R: CommandRunner, D: DependencyResolver>(
401	    ws: &Workspace<'_, R, D>,
402	    head: &str,
403	) -> Result<bool, GraphError> {
404	    let dir = super::release_decision::normalized_git_path(&ws.config.changesets_dir)?;
