631	/// Issues exactly one `git cat-file --batch` invocation requesting every
632	/// path in `paths` as `<commit>:<path>`, and returns each result in the
633	/// same order as `paths`.
634	///
635	/// `git cat-file --batch` reads one object identifier per line from stdin
636	/// and, for each, writes to stdout either:
637	///
638	/// ```text
639	/// <sha> SP <type> SP <size> LF
640	/// <content: exactly `size` bytes> LF
641	/// ```
642	///
643	/// or, if the object doesn't exist:
644	///
645	/// ```text
646	/// <object> SP missing LF
647	/// ```
648	///
649	/// (git also reports `<object> SP ambiguous LF` for a ref that resolves to
650	/// more than one object; `<commit>:<path>` syntax should never be
651	/// ambiguous, but it's checked for explicitly below rather than silently
652	/// falling through to the blob-header parse.)
653	///
654	/// This lets every canonical manifest's content at one commit be fetched in
655	/// a single subprocess round trip instead of one `git show` per manifest.
656	///
657	/// Parsing here is deliberately defensive rather than permissive: this
658	/// feeds [`derive_release_commit_decision`]'s trust-boundary comparison, so
659	/// any framing ambiguity -- an unrecognized header shape, a declared `size`
660	/// that doesn't fit the remaining output, a missing separator byte right
661	/// after the declared content length, a non-`blob` object type, or a
662	/// leftover/truncated tail once every requested path has been accounted
663	/// for -- fails the whole batch closed rather than guessing. Each expected
664	/// response is also matched against its exact requested object string
665	/// (rather than a generic "ends with ` missing`" pattern), so a manifest
666	/// path that happened to contain a space or colon can't be misread as a
667	/// different response shape. Silently misattributing one manifest's
668	/// content to a different path because an undetected desync shifted every
669	/// later offset would be a far worse failure mode than an outright
670	/// rejection.
671	fn batch_manifest_blobs_at<R: CommandRunner>(
672	    runner: &R,
673	    root: &std::path::Path,
674	    commit: &str,
675	    paths: &[&str],
676	) -> Result<Vec<BatchBlob>, GraphError> {
677	    if paths.is_empty() {
678	        return Ok(Vec::new());
679	    }
680	
681	    const BATCH_ARGS: [&str; 2] = ["cat-file", "--batch"];
682	
683	    let mut stdin = String::new();
684	    let objects: Vec<String> = paths
685	        .iter()
686	        .map(|path| {
687	            let object = format!("{commit}:{path}");
688	            stdin.push_str(&object);
689	            stdin.push('\n');
690	            object
691	        })
692	        .collect();
693	
694	    let output = runner.run_with_stdin("git", &BATCH_ARGS, root, stdin.as_bytes())?;
695	    if !output.success() {
696	        return Err(command_non_zero_exit("git", &BATCH_ARGS, &output));
697	    }
698	
699	    let mut rest = output.stdout.as_str();
700	    let mut results = Vec::with_capacity(objects.len());
701	    for object in &objects {
702	        let (header, after_header) = rest.split_once('\n').ok_or_else(|| {
703	            command_malformed_output(
704	                "git",
705	                &BATCH_ARGS,
706	                format!("truncated response: missing header line for `{object}`"),
707	            )
708	        })?;
709	
710	        if header == format!("{object} missing") {
711	            results.push(BatchBlob::Missing);
712	            rest = after_header;
713	            continue;
714	        }
715	        if header == format!("{object} ambiguous") {
716	            return Err(command_malformed_output(
717	                "git",
718	                &BATCH_ARGS,
719	                format!("object `{object}` is ambiguous"),
720	            ));
721	        }
722	
723	        let mut fields = header.split(' ');
724	        let sha = fields.next().ok_or_else(|| {
725	            command_malformed_output(
726	                "git",
727	                &BATCH_ARGS,
728	                format!("header for `{object}` is missing its sha field: `{header}`"),
729	            )
730	        })?;
731	        let object_type = fields.next().ok_or_else(|| {
732	            command_malformed_output(
733	                "git",
734	                &BATCH_ARGS,
735	                format!("header for `{object}` is missing its type field: `{header}`"),
736	            )
737	        })?;
738	        let size_field = fields.next().ok_or_else(|| {
739	            command_malformed_output(
740	                "git",
741	                &BATCH_ARGS,
742	                format!("header for `{object}` is missing its size field: `{header}`"),
743	            )
744	        })?;
745	        if fields.next().is_some() {
746	            // A well-formed header has exactly three space-separated
747	            // fields; anything else is not a shape this parser understands.
748	            return Err(command_malformed_output(
749	                "git",
750	                &BATCH_ARGS,
751	                format!("header for `{object}` has more than three fields: `{header}`"),
752	            ));
753	        }
754	        if sha.is_empty() || !sha.chars().all(|c| c.is_ascii_hexdigit()) {
755	            return Err(command_malformed_output(
756	                "git",
757	                &BATCH_ARGS,
758	                format!("header for `{object}` reports a non-hex sha: `{sha}`"),
759	            ));
760	        }
761	        if object_type != "blob" {
762	            // Every path requested here is a canonical manifest file, so a
763	            // resolved object must be a blob; a tree/commit/tag response
764	            // means the path resolved to something else entirely.
765	            return Err(command_malformed_output(
766	                "git",
767	                &BATCH_ARGS,
768	                format!("object `{object}` resolved to a `{object_type}`, not a blob"),
769	            ));
770	        }
771	        let size: usize = size_field.parse().map_err(|parse_error| {
772	            command_malformed_output(
773	                "git",
774	                &BATCH_ARGS,
775	                format!("header for `{object}` has a non-numeric size `{size_field}`: {parse_error}"),
776	            )
