   406	/// True when `HEAD`'s tree still has an unconsumed changeset file, read from the commit, not the working tree.
   407	fn head_has_pending_changeset<R: CommandRunner, D: DependencyResolver>(
   408	    ws: &Workspace<'_, R, D>,
   409	    head: &str,
   410	) -> Result<bool, GraphError> {
   411	    let dir = super::release_decision::normalized_git_path(&ws.config.changesets_dir)?;
   412	    let spec = format!("{head}:{dir}");
   413	    if !head_object_exists(ws, &spec)? {
   414	        // The changesets directory didn't exist at HEAD (e.g. the first `version` run); nothing left pending.
   415	        return Ok(false);
   416	    }
   417	    let output = ws
   418	        .runner
   419	        .run("git", &["ls-tree", "--name-only", &spec], &ws.root)
   420	        .map_err(GraphError::Command)?;
   421	    if !output.success() {
   422	        return Ok(false);
   423	    }
   424	    Ok(output.stdout.lines().any(|name| {
   425	        let name = name.trim();
   426	        name.ends_with(".md") && name != "README.md"
   427	    }))
   428	}
