415	fn head_has_pending_changeset<R: CommandRunner, D: DependencyResolver>(
416	    ws: &Workspace<'_, R, D>,
417	    head: &str,
418	) -> Result<bool, GraphError> {
419	    let dir = super::release_decision::normalized_git_path(&ws.config.changesets_dir)?;
