428	        .map_err(GraphError::Command)?;
429	    if !output.success() {
430	        return Err(GraphError::Command(callisto_model::CommandError::Failed {
431	            program: "git".to_string(),
432	            exit_code: output.exit_code,
433	            stderr: output.stderr,
