414	/// True when `HEAD`'s tree still has an unconsumed changeset file, read from the commit, not the working tree.
415	fn head_has_pending_changeset<R: CommandRunner, D: DependencyResolver>(
416	    ws: &Workspace<'_, R, D>,
417	    head: &str,
418	) -> Result<bool, GraphError> {
419	    let dir = super::release_decision::normalized_git_path(&ws.config.changesets_dir)?;
420	    let spec = format!("{head}:{dir}");
421	    if !head_object_exists(ws, &spec)? {
422	        // The changesets directory didn't exist at HEAD (e.g. the first `version` run); nothing left pending.
423	        return Ok(false);
424	    }
425	    let output = ws
426	        .runner
427	        .run("git", &["ls-tree", "--name-only", &spec], &ws.root)
428	        .map_err(GraphError::Command)?;
429	    if !output.success() {
430	        return Err(GraphError::Command(callisto_model::CommandError::Failed {
431	            program: "git".to_string(),
432	            exit_code: output.exit_code,
433	            stderr: output.stderr,
434	        }));
435	    }
436	    Ok(output.stdout.lines().any(|name| {
437	        let name = name.trim();
438	        name.ends_with(".md") && name != "README.md"
439	    }))
440	}
