410	/// entries all safely fall back to `None` (a plain `?`-chain), which causes
411	/// `read_npm_membership` to admit-all.
412	fn read_package_json_workspaces(root: &Path) -> Option<Vec<String>> {
413	    let content = std::fs::read_to_string(root.join(ManifestFormat::PackageJson.file_name())).ok()?;
414	    let val: serde_json::Value = serde_json::from_str(&content).ok()?;
415	    let field = val.get("workspaces")?;
416	    let arr = field.as_array()?;
417	    let mut out = Vec::with_capacity(arr.len());
418	    for v in arr {
419	        out.push(v.as_str()?.to_string());
420	    }
421	    Some(out)
422	}
