394	/// a non-string sequence element all safely fall back to `None` (which
395	/// causes `read_npm_membership` to fall through to
396	/// `read_package_json_workspaces` or admit-all).
397	fn read_pnpm_packages(root: &Path) -> Option<Vec<String>> {
398	    let content = std::fs::read_to_string(root.join("pnpm-workspace.yaml")).ok()?;
399	    let docs = yaml_rust2::YamlLoader::load_from_str(&content).ok()?;
400	    let doc = docs.first()?;
401	    let packages = doc["packages"].as_vec()?;
402	    let mut out = Vec::with_capacity(packages.len());
403	    for item in packages {
404	        out.push(item.as_str()?.to_string());
405	    }
406	    Some(out)
407	}
