  5	/// A [`GlobSet`] pair implementing npm/pnpm/Yarn-style workspace glob
  6	/// negation. `globset`'s `GlobSetBuilder` has no negation concept of its
  7	/// own -- a pattern with a leading `!` is just another literal
  8	/// positive-match glob to it, so `!packages/excluded` compiles into a glob
  9	/// that matches paths literally starting with the character `!`, which
 10	/// never matches any real path. That silently no-ops the negation instead
 11	/// of excluding anything.
 12	///
 13	/// A path is admitted only when it matches at least one `positive` pattern
 14	/// and matches none of the `negative` (`!`-stripped) patterns -- mirroring
 15	/// how npm/pnpm/Yarn actually resolve workspace globs (later patterns can
 16	/// negate earlier ones; a leading `!` excludes). A positive-only pattern
 17	/// list behaves exactly as a plain [`GlobSet`] would. An all-negative list
 18	/// has an empty positive set, so `is_match` is always `false` -- there is no
 19	/// positive baseline for the negation to carve an exclusion out of.
 20	pub(crate) struct NegatableGlobSet {
 21	    positive: GlobSet,
 22	    negative: GlobSet,
 23	}
 24	
 25	impl NegatableGlobSet {
 26	    pub(crate) fn is_match(&self, path: &Path) -> bool {
 27	        self.positive.is_match(path) && !self.negative.is_match(path)
 28	    }
 29	
 30	    pub(crate) fn empty() -> Self {
 31	        NegatableGlobSet {
 32	            positive: GlobSet::empty(),
 33	            negative: GlobSet::empty(),
 34	        }
 35	    }
 36	}
 37	
 38	/// Builds a [`NegatableGlobSet`] from a list of glob strings, matched with
 39	/// `literal_separator(true)` semantics (`*` does not cross `/`; `**` does)
 40	/// against forward-slash-normalized, workspace-relative paths. An entry
 41	/// with a leading `!` is treated as a negative (exclusion) pattern -- see
 42	/// [`NegatableGlobSet`].
 43	///
 44	/// Per-entry glob-compile-failure rule: an entry that fails to compile is
 45	/// skipped and treated as never-matching; every other syntactically valid
 46	/// entry in the same list is still compiled and matched normally. Never
 47	/// panics, never returns an error.
 48	pub(crate) fn build_globset(entries: &[String]) -> NegatableGlobSet {
 49	    let mut positive = GlobSetBuilder::new();
 50	    let mut negative = GlobSetBuilder::new();
 51	    for entry in entries {
 52	        let (builder, pattern) = match entry.strip_prefix('!') {
 53	            Some(rest) => (&mut negative, rest),
 54	            None => (&mut positive, entry.as_str()),
 55	        };
 56	        if let Ok(glob) = GlobBuilder::new(pattern).literal_separator(true).build() {
 57	            builder.add(glob);
 58	        }
 59	    }
 60	    NegatableGlobSet {
 61	        positive: positive.build().unwrap_or_else(|_| GlobSet::empty()),
 62	        negative: negative.build().unwrap_or_else(|_| GlobSet::empty()),
 63	    }
 64	}
