   442	    /// Resolves within the declaring ecosystem, using PEP 503 equivalence for Python.
   443	    /// Ambiguous Python names and cross-ecosystem candidates produce a warning and no match.
   444	    pub fn resolve_native_with_fallback<'a>(
   445	        &'a self,
   446	        eco: Ecosystem,
   447	        name: &str,
   448	        diagnostics: &mut Vec<callisto_model::Diagnostic>,
   449	    ) -> Option<&'a PackageId> {
   450	        match self.native_in_ecosystem(eco, name) {
   451	            Ok(Some(id)) => return Some(id),
   452	            Ok(None) => {}
   453	            Err(error) => {
   454	                diagnostics.push(callisto_model::Diagnostic {
   455	                    code: callisto_model::DiagnosticCode::UnknownPackage,
   456	                    severity: callisto_model::DiagnosticSeverity::Warning,
   457	                    message: error.to_string(),
   458	                    package: None,
   459	                    path: None,
   460	                    escalated_by: None,
   461	                    governed_by: None,
   462	                });
   463	                return None;
   464	            }
   465	        }
   466	
   467	        // Cross-ecosystem fallback: collect unique IDs from other ecosystems,
   468	        // keeping each candidate's own native name (`n`, the map key) rather
   469	        // than its owning package's primary name (`id.name()`) -- a
   470	        // dual-manifest package's manifests can declare different names, and
   471	        // the diagnostic must name what the *other* ecosystem actually calls
   472	        // it, not this package's unrelated primary/display name.
   473	        let mut candidates: Vec<(Ecosystem, &str, &PackageId)> = self
   474	            .native
   475	            .iter()
   476	            .filter(|((e, n), _)| *e != eco && n == name)
   477	            .map(|((e, n), id)| (*e, n.as_str(), id))
   478	            .collect();
