   414	    /// a diagnostic.
   415	    pub fn resolve_native(&self, eco: Ecosystem, name: &str) -> Option<&PackageId> {
   416	        match self.native_in_ecosystem(eco, name) {
   417	            Ok(Some(id)) => return Some(id),
   418	            Ok(None) => {}
   419	            Err(_) => return None,
   420	        }
   421	
   422	        // Cross-ecosystem fallback.
   423	        let mut candidates: Vec<&PackageId> = self
   424	            .native
   425	            .iter()
   426	            .filter(|((e, n), _)| *e != eco && n == name)
   427	            .map(|(_, id)| id)
   428	            .collect();
