119	            // the fallback admit-all (no restriction present for that ecosystem) doesn't make
120	            // this directory a real, deliberate workspace member; only a genuine members/
121	            // workspaces match does.
122	            let any_sibling_admitted = parsed
123	                .iter()
124	                .any(|(ecosystem, _, identity)| identity.name.is_some() && admits_explicitly(*ecosystem));
125	
126	            for (manifest_path, message) in failures {
127	                // Determine which ecosystem this failed manifest belongs to from its
128	                // file name, to check its own membership independent of any sibling.
129	                let ecosystem = Ecosystem::CANONICAL.into_iter().find(|eco| {
130	                    eco.canonical_manifest_format()
131	                        .is_some_and(|f| Some(f.file_name()) == manifest_path.file_name().and_then(|n| n.to_str()))
132	                });
133	                let self_admitted = ecosystem.is_some_and(admits_explicitly);
134	                if self_admitted || any_sibling_admitted {
135	                    return Err(LocateError::ManifestParseError {
136	                        path: manifest_path,
137	                        message,
138	                    });
139	                }
140	                eprintln!("{}", unparseable_manifest_warning(&manifest_path, &message));
141	            }
142	
143	            for (ecosystem, content, identity) in parsed {
144	                let Some(name) = identity.name else {
145	                    continue;
146	                };
147	
148	                // A private, versionless root package.json (standard npm/pnpm workspace-root
149	                // layout, e.g. `@changesets/cli`) declares a name only to hold `workspaces`; it
150	                // is never itself a released package, so it never becomes a project.
151	                if is_root
152	                    && ecosystem == Ecosystem::Npm
153	                    && identity.version.is_none()
154	                    && callisto_manifests::npm_declares_private(&content)
155	                {
156	                    continue;
157	                }
158	
159	                let admitted = admits(ecosystem);
160	                let id = PackageId::parse(&name).unwrap_or_else(|_| PackageId::Bare(name.clone()));
161	                let project = ProjectRoot {
162	                    id,
163	                    path: rel.clone(),
164	                    ecosystem,
165	                };
166	                if admitted {
167	                    results.push(project);
168	                } else if ecosystem == Ecosystem::Npm && callisto_manifests::npm_role_from_source(&content).is_some() {
169	                    platform_candidates.push(project);
170	                }
171	            }
172	        }
173	
174	        results.sort_by(|a, b| (&a.path, a.ecosystem).cmp(&(&b.path, b.ecosystem)));
175	        platform_candidates.sort_by(|a, b| a.path.cmp(&b.path));
176	        Ok((results, platform_candidates))
177	    }
